<section><h1><?= dts_escape($pageTitle) ?></h1><form method="post" action="<?= dts_escape($formAction) ?>" class="form-grid"><?php foreach($fields as $field):?><label><?= dts_escape($field['label']) ?><?php if(($field['type']??'text')==='select'):?><select name="<?= dts_escape($field['name']) ?>" <?= !empty($field['required'])?'required':'' ?>><?php if(array_key_exists('empty',$field)):?><option value=""><?= dts_escape($field['empty']) ?></option><?php endif;?><?php foreach(($field['options']??array()) as $option):$ov=(string)$option[$field['optionValue']];?><option value="<?= dts_escape($ov) ?>" <?= (string)($field['value']??'')===$ov?'selected':'' ?>><?= dts_escape($option[$field['optionLabel']]??$ov) ?></option><?php endforeach;?></select><?php elseif(($field['type']??'text')==='textarea'):?><textarea name="<?= dts_escape($field['name']) ?>"><?= dts_escape($field['value']??'') ?></textarea><?php else:?><input name="<?= dts_escape($field['name']) ?>" value="<?= dts_escape($field['value']??'') ?>" <?= !empty($field['required'])?'required':'' ?>><?php endif;?></label><?php endforeach;?><button type="submit">Save</button></form></section>
